-- Migration additive : conserve les données du premier prototype.
CREATE TABLE memberships_v2 (user_id TEXT NOT NULL REFERENCES users(id), condominium_id TEXT NOT NULL REFERENCES condominiums(id), role TEXT NOT NULL CHECK(role IN ('manager','owner','tenant','supplier','council')), revoked_at TEXT, PRIMARY KEY(user_id, condominium_id));
INSERT INTO memberships_v2 SELECT * FROM memberships;
DROP TABLE memberships;
ALTER TABLE memberships_v2 RENAME TO memberships;
CREATE TABLE fiscal_years (condominium_id TEXT NOT NULL REFERENCES condominiums(id), year INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open', PRIMARY KEY(condominium_id,year));
INSERT INTO fiscal_years SELECT id,fiscal_year,'open' FROM condominiums;
CREATE TABLE buildings (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), name TEXT NOT NULL, has_intercom INTEGER NOT NULL DEFAULT 0, intercom_display_offset INTEGER, intercom_program_offset INTEGER, notes TEXT NOT NULL DEFAULT '');
ALTER TABLE lots ADD COLUMN building_id TEXT REFERENCES buildings(id);
ALTER TABLE lots ADD COLUMN lot_type TEXT NOT NULL DEFAULT 'apartment';
ALTER TABLE lots ADD COLUMN area_m2 TEXT;
ALTER TABLE lots ADD COLUMN use_type TEXT NOT NULL DEFAULT 'residential';
ALTER TABLE lots ADD COLUMN declared_activity TEXT NOT NULL DEFAULT '';
ALTER TABLE lots ADD COLUMN apartment_number TEXT NOT NULL DEFAULT '';
ALTER TABLE lots ADD COLUMN parent_lot_id TEXT REFERENCES lots(id);
ALTER TABLE lots ADD COLUMN intercom_display TEXT NOT NULL DEFAULT '';
ALTER TABLE lots ADD COLUMN intercom_program TEXT NOT NULL DEFAULT '';
ALTER TABLE lots ADD COLUMN mailbox TEXT NOT NULL DEFAULT '';
ALTER TABLE lots ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE lot_relations (id TEXT PRIMARY KEY, lot_id TEXT NOT NULL REFERENCES lots(id), user_id TEXT NOT NULL REFERENCES users(id), relation TEXT NOT NULL CHECK(relation IN ('owner','occupant')), tenure TEXT CHECK(tenure IN ('owner','tenant')), valid_from TEXT NOT NULL, valid_until TEXT, CHECK(valid_until IS NULL OR valid_until>valid_from));
INSERT INTO lot_relations SELECT 'owner-'||id,id,owner_id,'owner',NULL,'2020-01-01',NULL FROM lots WHERE owner_id IS NOT NULL;
CREATE TABLE contact_preferences (user_id TEXT NOT NULL REFERENCES users(id), condominium_id TEXT NOT NULL REFERENCES condominiums(id), visible INTEGER NOT NULL DEFAULT 0, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', PRIMARY KEY(user_id,condominium_id));
CREATE TABLE ops_items (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), kind TEXT NOT NULL CHECK(kind IN ('equipment','contract','visit','event','access')), title TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('residents','owners','management','lot')), lot_id TEXT REFERENCES lots(id), assigned_to TEXT REFERENCES users(id), fiscal_year INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), updated_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX ops_context ON ops_items(condominium_id,kind,fiscal_year);
ALTER TABLE records ADD COLUMN access_scope TEXT NOT NULL DEFAULT 'owners';
ALTER TABLE records ADD COLUMN fiscal_year INTEGER NOT NULL DEFAULT 2026;
ALTER TABLE records ADD COLUMN equipment_id TEXT REFERENCES ops_items(id);
ALTER TABLE records ADD COLUMN ops_id TEXT REFERENCES ops_items(id);
ALTER TABLE records ADD COLUMN created_by TEXT REFERENCES users(id);
UPDATE records SET created_by=updated_by;
CREATE TABLE item_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, resource_id TEXT NOT NULL, condominium_id TEXT NOT NULL, actor_id TEXT NOT NULL, version INTEGER NOT NULL, snapshot TEXT NOT NULL, happened_at TEXT NOT NULL);
CREATE TRIGGER ops_created AFTER INSERT ON ops_items BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'created',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER ops_updated AFTER UPDATE ON ops_items BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,OLD.condominium_id,NEW.updated_by,OLD.version,OLD.payload,NEW.updated_at); INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'updated',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER record_revision BEFORE UPDATE ON records BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,OLD.condominium_id,NEW.updated_by,OLD.version,OLD.payload,NEW.updated_at); END;
